using Captovix;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Reflection;
using System.Windows.Controls;
internal static class Program
{
 static int n;static void Check(bool b,string s){if(!b)throw new Exception(s);n++;Console.WriteLine("PASS: "+s);}
 [STAThread]static int Main(){try{
 var source=ImageTransfer.Bitmap(500,400,new byte[500*400*4]);var raw=Enumerable.Range(0,200*100).SelectMany(_=>new byte[]{0,0,255,255}).ToArray();var image=ImageTransfer.Bitmap(200,100,raw);var layer=new Annotation{Kind=AnnotationKind.ImageLayer,X1=100,Y1=100,X2=300,Y2=300,PixelPng=RasterPixels.Encode(image),ImageStyle=new()};var doc=new EditorDocument{OriginalWidth=500,OriginalHeight=400,Annotations=[layer]};var pixels=ImageTransfer.Bgra(EditorRenderer.Render(source,doc));Check(pixels[(110*500+110)*4+3]==0&&pixels[(180*500+110)*4+2]==255,"Fit letterboxes with source color preserved");layer.ImageStyle.Fit=ImageFit.Fill;pixels=ImageTransfer.Bgra(EditorRenderer.Render(source,doc));Check(pixels[(110*500+110)*4+2]==255,"Fill covers slot");layer.ImageStyle.Radius=40;pixels=ImageTransfer.Bgra(EditorRenderer.Render(source,doc));Check(pixels[(100*500+100)*4+3]==0,"Rounded slot clips corner alpha");
 var session=new EditorSession(doc);var surface=new EditorSurface();surface.Load(source,session);surface.Tool=EditorTool.Select;surface.SelectIds([layer.Id]);surface.ContentPanEnabled=true;surface.PointerDown(new(200,200));surface.PointerUp(new(240,200));Check(Math.Abs(layer.ImageStyle.PanX-.3)<.001&&layer.X1==100,"Content dragging pans fill without moving slot");session.Undo();Check(session.Document.Annotations[0].ImageStyle!.PanX==.5,"Pan gesture is one Undo");
 var export=ImageTransfer.Bgra(surface.Flatten());surface.SetZoom(.25);Check(ImageTransfer.Bgra(surface.Flatten()).SequenceEqual(export),"Composition export is independent of zoom");
 foreach(var kind in Enum.GetValues<CalloutStyle>()){var a=new Annotation{Kind=AnnotationKind.Callout,CalloutStyle=kind,CalloutBodyPivot=true,X1=100,Y1=50,X2=136,Y2=86,Text="Nhập nội dung",TextPadding=30,FontSize=28};EditorRenderer.FitText(a,new(0,0,500,400));Check(a.Width>=100&&a.Height>=36&&EditorRenderer.TextContent(a).Width>=100,"Callout fits readable content without vertical runaway: "+kind);a.Text=new string('W',5000);EditorRenderer.FitText(a,new(0,0,500,400));Check(a.Height<=100000&&a.Height>400,"Long callout retains text beyond old canvas, within safe annotation bound: "+kind);}
 var app=new App();app.InitializeComponent();var window=new MainWindow();Check(window.Title.Contains("1.17.0")&&window.WindowState==WindowState.Maximized,"App starts current version without XAML callback exception");Check(((FrameworkElement)window.FindName("UpdateConfiguration")).Visibility==Visibility.Collapsed,"Update URL configuration is hidden");var hotkeys=(FrameworkElement)window.FindName("HotkeysSettingsView");var capture=(FrameworkElement)window.FindName("CaptureSettingsView");Check(hotkeys.Parent!=capture&&hotkeys.Parent==capture.Parent,"Hotkey and capture modules are separate views");Check(((EditorSurface)window.FindName("Surface")).CalloutDefaults.TextPadding==30,"New callout default padding is 30 pixels");Check(((Button)window.FindName("CaptureButton")).Content is StackPanel&&((Button)window.FindName("RecordButton")).Content is StackPanel,"Capture and record use vector icon content");window.Close();Console.WriteLine($"{n} composition Windows checks passed.");return 0;
 }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
